const item = $input.first();
const out = item.json.output || {};
const errors = [];

const score = Number(out.score);
const allowed = ['interview', 'maybe', 'reject'];

if (!Number.isFinite(score) || score < 0 || score > 100)
  errors.push('Score must be a number between 0 and 100.');
if (!allowed.includes(out.recommendation))
  errors.push('Recommendation must be interview, maybe or reject.');
if (!Array.isArray(out.matched_requirements))
  errors.push('matched_requirements must be a list.');
if (!Array.isArray(out.missing_requirements))
  errors.push('missing_requirements must be a list.');

// Recommendation must match the score range
if (errors.length === 0) {
  const expected = score >= 70 ? 'interview' : score >= 40 ? 'maybe' : 'reject';
  if (expected !== out.recommendation) errors.push(`Recommendation "${out.recommendation}" does not match score ${score}.`);
}

return [{
  json: {
    score,
    recommendation: out.recommendation,
    matched: (out.matched_requirements || []).join(', '),
    missing: (out.missing_requirements || []).join(', '),
    summary: out.summary || '',
    valid: errors.length === 0,
    errors,
    errorText: errors.join(' | '),
  },
}];

