parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "yearsExperience": {
      "type": "number",
      "description": "Total years of professional work experience. Count internships proportionally. Use 0 if none."
    },
    "topSkills": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Top 8 technical skills explicitly mentioned in the CV."
    },
    "education": {
      "type": "string",
      "description": "Highest degree and field of study. Empty string if not mentioned."
    },
    "languages": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Spoken languages mentioned in the CV."
    }
  },
  "required": ["yearsExperience", "topSkills"]
}
